#!/usr/bin/env python3
"""SYNTHETIC FIXTURE - generates a tiny LeRobot-v3-layout (or v2-layout) dataset for offline tests.

Nothing here is real robot data: frames are procedurally drawn moving squares, proprio/actions are
smooth sinusoids, task strings are prefixed with ``SYNTHETIC FIXTURE``. The *layout* mirrors what
``eeb.data.lerobot_loader`` verified on the Hub (2026-10-08):

v3 (default) ::

    meta/info.json                                codebase_version "v3.0", data_path/video_path templates, features
    meta/tasks.parquet          | meta/tasks.jsonl              (fallback)
    meta/episodes/chunk-000/file-000.parquet | .jsonl           (fallback)
    data/chunk-000/file-000.parquet          | .npz             (fallback; raw uint8 frames)
    images/<key>/episode_XXXXXX/frame_XXXXXX.png                (image_mode="png_dir")
    videos/<key>/chunk-000/file-000.mkv|mp4                     (image_mode="video"; needs `av`)

v2 (``layout="v2"``) ::

    meta/info.json  codebase_version "v2.0"      meta/episodes.jsonl   meta/tasks.jsonl
    data/chunk-000/episode_000000.parquet | .npz  (one episode per file; keys image/wrist_image/state/actions)

Fallback policy (``data_format``): ``"auto"`` writes parquet when ``pyarrow`` imports, else the
documented JSONL (metadata) + NPZ (frame table) fallback that the loader also accepts; ``"fallback"``
forces it (used by the tests to exercise the pure-NumPy path even when pyarrow is installed).

Usage::

    python tests/fixtures/make_mini_lerobot.py --out /tmp/mini_lerobot [--layout v2] [--image-mode png_dir|video]
"""

from __future__ import annotations

import argparse
from dataclasses import dataclass, field
import io
import json
import os
from pathlib import Path
import sys
from typing import Any, Dict, List, Optional, Sequence, Tuple

import numpy as np

SYNTHETIC_LABEL = "SYNTHETIC FIXTURE (procedurally generated by tests/fixtures/make_mini_lerobot.py; not real robot data)"
STATE_DIM = 8
ACTION_DIM = 7


@dataclass
class MiniEpisode:
  episode_index: int
  task: str
  task_index: int
  timestamps: np.ndarray                 # float32 [T]
  state: np.ndarray                      # float32 [T, 8]
  action: np.ndarray                     # float32 [T, 7]
  images: Dict[str, np.ndarray]          # camera -> uint8 [T, H, W, 3]


@dataclass
class MiniLeRobot:
  root: Path
  layout: str
  data_format: str                       # "parquet" | "fallback"
  image_mode: str                        # "embedded" | "png_dir" | "video"
  fps: float
  cameras: Tuple[str, ...]
  episodes: List[MiniEpisode] = field(default_factory=list)
  files: List[str] = field(default_factory=list)

  def feature_key(self, camera: str) -> str:
    return camera if self.layout == "v2" else f"observation.images.{camera}"


# --------------------------------------------------------------------------------------------
# Synthetic content
# --------------------------------------------------------------------------------------------
def _draw_frame(h: int, w: int, t: int, ep: int, cam_idx: int, rng: np.random.Generator) -> np.ndarray:
  """Gradient background + a moving bright square; unique per (episode, camera, step)."""
  yy, xx = np.mgrid[0:h, 0:w]
  base = np.stack([
      (xx * 255 // max(w - 1, 1)),
      (yy * 255 // max(h - 1, 1)),
      np.full((h, w), 40 + 60 * cam_idx + 20 * ep),
  ], axis=-1).astype(np.int32)
  s = max(h // 8, 4)
  cx = (5 + 3 * t + 11 * ep + 7 * cam_idx) % max(w - s, 1)
  cy = (7 + 2 * t + 5 * ep) % max(h - s, 1)
  base[cy:cy + s, cx:cx + s] = np.array([250, 250 - 10 * cam_idx, 30 + 20 * t], dtype=np.int32)
  noise = rng.integers(0, 6, size=(h, w, 3), dtype=np.int32)
  return np.clip(base + noise, 0, 255).astype(np.uint8)


def _make_episode(ep: int, n_steps: int, cameras: Sequence[str], h: int, w: int, fps: float, rng: np.random.Generator) -> MiniEpisode:
  t = np.arange(n_steps, dtype=np.float64)
  timestamps = (t / fps).astype(np.float32)
  phase = 0.37 * ep
  state = np.stack([np.sin(0.21 * t + phase + k) * (0.3 + 0.05 * k) for k in range(STATE_DIM)], axis=1).astype(np.float32)
  action = np.stack([np.cos(0.17 * t + phase + k) * 0.5 for k in range(ACTION_DIM)], axis=1).astype(np.float32)
  action[:, -1] = np.where(t > n_steps / 2, 1.0, -1.0)  # gripper open/close like LIBERO
  images = {cam: np.stack([_draw_frame(h, w, int(i), ep, ci, rng) for i in range(n_steps)]) for ci, cam in enumerate(cameras)}
  task = f"{SYNTHETIC_LABEL.split(' (')[0]}: put the {['red', 'blue', 'green', 'yellow'][ep % 4]} block in the bowl (episode {ep})"
  return MiniEpisode(episode_index=ep, task=task, task_index=ep, timestamps=timestamps, state=state, action=action, images=images)


def _png_bytes(img: np.ndarray) -> bytes:
  from PIL import Image

  buf = io.BytesIO()
  Image.fromarray(img).save(buf, format="PNG")
  return buf.getvalue()


# --------------------------------------------------------------------------------------------
# Writers
# --------------------------------------------------------------------------------------------
def _pyarrow_available() -> bool:
  try:
    import pyarrow  # noqa: F401
    import pyarrow.parquet  # noqa: F401
    return True
  except ImportError:
    return False


def _write_json(path: Path, obj: Any) -> None:
  path.parent.mkdir(parents=True, exist_ok=True)
  with open(path, "w", encoding="utf-8") as f:
    json.dump(obj, f, indent=2)
    f.write("\n")


def _write_jsonl(path: Path, rows: Sequence[Dict[str, Any]]) -> None:
  path.parent.mkdir(parents=True, exist_ok=True)
  with open(path, "w", encoding="utf-8") as f:
    for r in rows:
      f.write(json.dumps(r) + "\n")


def _write_frame_table_parquet(path: Path, columns: Dict[str, Any], image_cols: Sequence[str], fixed_size: bool) -> None:
  import pyarrow as pa
  import pyarrow.parquet as pq

  arrays: Dict[str, Any] = {}
  for name, col in columns.items():
    if name in image_cols:
      arrays[name] = pa.array(col, type=pa.struct([("bytes", pa.binary()), ("path", pa.string())]))
    elif isinstance(col, np.ndarray) and col.ndim == 2:
      vals = [list(map(float, row)) for row in col]
      typ = pa.list_(pa.float32(), col.shape[1]) if fixed_size else pa.list_(pa.float32())
      arrays[name] = pa.array(vals, type=typ)
    elif isinstance(col, np.ndarray) and col.dtype == np.float32:
      arrays[name] = pa.array(col.tolist(), type=pa.float32())
    elif isinstance(col, np.ndarray):
      arrays[name] = pa.array(col.tolist(), type=pa.int64())
    else:
      arrays[name] = pa.array(col)
  path.parent.mkdir(parents=True, exist_ok=True)
  pq.write_table(pa.table(arrays), str(path))


def _write_frame_table_npz(path: Path, columns: Dict[str, Any]) -> None:
  path.parent.mkdir(parents=True, exist_ok=True)
  np.savez_compressed(path, **{k: np.asarray(v) for k, v in columns.items()})


def _write_video(path: Path, frames: np.ndarray, fps: float, codec: str) -> None:
  """Write ``uint8[N,H,W,3]`` frames; ffv1 (lossless planar RGB, .mkv) or av1/libx264 (.mp4)."""
  import av

  os.environ.setdefault("SVT_LOG", "1")  # silence SVT-AV1 banner

  path.parent.mkdir(parents=True, exist_ok=True)
  with av.open(str(path), mode="w") as container:
    stream = container.add_stream(codec, rate=int(round(fps)))
    stream.width = int(frames.shape[2])
    stream.height = int(frames.shape[1])
    if codec == "ffv1":
      stream.pix_fmt = "bgr0"           # packed RGB: lossless round trip of rgb24 frames (verified)
    else:
      stream.pix_fmt = "yuv420p"
      if codec in ("libsvtav1", "av1"):
        stream.options = {"preset": "8", "crf": "20"}
    for arr in frames:
      frame = av.VideoFrame.from_ndarray(np.ascontiguousarray(arr), format="rgb24")
      for packet in stream.encode(frame):
        container.mux(packet)
    for packet in stream.encode():
      container.mux(packet)


# --------------------------------------------------------------------------------------------
# Main generator
# --------------------------------------------------------------------------------------------
def make_mini_lerobot(
    root: str | os.PathLike[str],
    *,
    n_episodes: int = 2,
    n_steps: int = 10,
    cameras: Sequence[str] = ("image", "wrist_image"),
    height: int = 64,
    width: int = 64,
    fps: float = 10.0,
    seed: int = 0,
    layout: str = "v3",
    image_mode: str = "embedded",
    data_format: str = "auto",
    video_codec: str = "ffv1",
) -> MiniLeRobot:
  """Generate the synthetic dataset under ``root`` and return ground truth for round-trip tests."""
  if layout not in ("v3", "v2"):
    raise ValueError("layout must be 'v3' or 'v2'")
  if image_mode not in ("embedded", "png_dir", "video"):
    raise ValueError("image_mode must be embedded | png_dir | video")
  if data_format == "auto":
    data_format = "parquet" if _pyarrow_available() else "fallback"
  if data_format == "parquet" and not _pyarrow_available():
    raise ImportError("data_format='parquet' requested but pyarrow is not installed (use data_format='fallback')")
  if data_format not in ("parquet", "fallback"):
    raise ValueError("data_format must be auto | parquet | fallback")
  root = Path(root)
  root.mkdir(parents=True, exist_ok=True)
  rng = np.random.default_rng(seed)
  cams = tuple(cameras)
  ds = MiniLeRobot(root=root, layout=layout, data_format=data_format, image_mode=image_mode, fps=float(fps), cameras=cams)
  ds.episodes = [_make_episode(ep, n_steps, cams, height, width, fps, rng) for ep in range(n_episodes)]
  total_frames = n_episodes * n_steps
  is_v3 = layout == "v3"
  cam_keys = {cam: ds.feature_key(cam) for cam in cams}
  state_key = "observation.state" if is_v3 else "state"
  action_key = "action" if is_v3 else "actions"
  video_ext = ".mkv" if (image_mode == "video" and video_codec == "ffv1") else ".mp4"

  # ---- meta/info.json ----
  features: Dict[str, Any] = {}
  for cam, key in cam_keys.items():
    if image_mode == "video":
      features[key] = {
          "dtype": "video", "shape": [height, width, 3], "names": ["height", "width", "channel"],
          "info": {"video.height": height, "video.width": width, "video.codec": video_codec, "video.pix_fmt": "bgr0" if video_codec == "ffv1" else "yuv420p",
                   "video.is_depth_map": False, "video.fps": fps, "video.channels": 3, "has_audio": False},
      }
    else:
      features[key] = {"dtype": "image", "shape": [height, width, 3], "names": ["height", "width", "channel"]}
  features[state_key] = {"dtype": "float32", "shape": [STATE_DIM], "names": ["state"]}
  features[action_key] = {"dtype": "float32", "shape": [ACTION_DIM], "names": ["actions"]}
  for k, dt in (("timestamp", "float32"), ("frame_index", "int64"), ("episode_index", "int64"), ("index", "int64"), ("task_index", "int64")):
    features[k] = {"dtype": dt, "shape": [1], "names": None}
  info: Dict[str, Any] = {
      "_note": SYNTHETIC_LABEL,
      "codebase_version": "v3.0" if is_v3 else "v2.0",
      "robot_type": "synthetic_panda",
      "total_episodes": n_episodes,
      "total_frames": total_frames,
      "total_tasks": n_episodes,
      "chunks_size": 1000,
      "fps": fps,
      "splits": {"train": f"0:{n_episodes}"},
      "features": features,
  }
  if is_v3:
    info["data_path"] = "data/chunk-{chunk_index:03d}/file-{file_index:03d}.parquet"
    info["video_path"] = "videos/{video_key}/chunk-{chunk_index:03d}/file-{file_index:03d}" + video_ext
    info["data_files_size_in_mb"] = 100
    info["video_files_size_in_mb"] = 500
  else:
    info["total_videos"] = n_episodes * len(cams) if image_mode == "video" else 0
    info["total_chunks"] = 1
    info["data_path"] = "data/chunk-{episode_chunk:03d}/episode_{episode_index:06d}.parquet"
    info["video_path"] = "videos/chunk-{episode_chunk:03d}/{video_key}/episode_{episode_index:06d}" + video_ext
  _write_json(root / "meta" / "info.json", info)
  _write_json(root / "meta" / "stats.json", {"_note": SYNTHETIC_LABEL})
  ds.files += ["meta/info.json", "meta/stats.json"]

  # ---- tasks ----
  task_rows = [{"task_index": e.task_index, "task": e.task} for e in ds.episodes]
  if is_v3 and data_format == "parquet":
    import pyarrow as pa
    import pyarrow.parquet as pq

    pq.write_table(pa.table({"task_index": pa.array([r["task_index"] for r in task_rows], pa.int64()), "__index_level_0__": pa.array([r["task"] for r in task_rows], pa.string())}), str(root / "meta" / "tasks.parquet"))
    ds.files.append("meta/tasks.parquet")
  else:
    _write_jsonl(root / "meta" / "tasks.jsonl", task_rows)
    ds.files.append("meta/tasks.jsonl")

  # ---- episodes metadata ----
  ep_rows: List[Dict[str, Any]] = []
  cursor = 0
  for e in ds.episodes:
    row: Dict[str, Any] = {"episode_index": e.episode_index, "tasks": [e.task], "length": n_steps}
    if is_v3:
      row.update({"data/chunk_index": 0, "data/file_index": 0, "dataset_from_index": cursor, "dataset_to_index": cursor + n_steps})
      if image_mode == "video":
        for cam, key in cam_keys.items():
          row[f"videos/{key}/chunk_index"] = 0
          row[f"videos/{key}/file_index"] = 0
          row[f"videos/{key}/from_timestamp"] = cursor / fps
          row[f"videos/{key}/to_timestamp"] = (cursor + n_steps) / fps
    ep_rows.append(row)
    cursor += n_steps
  if is_v3:
    if data_format == "parquet":
      import pyarrow as pa
      import pyarrow.parquet as pq

      cols: Dict[str, Any] = {}
      for k in ep_rows[0]:
        vals = [r[k] for r in ep_rows]
        if k == "tasks":
          cols[k] = pa.array(vals, pa.list_(pa.string()))
        elif isinstance(vals[0], float):
          cols[k] = pa.array(vals, pa.float64())
        else:
          cols[k] = pa.array(vals, pa.int64())
      p = root / "meta" / "episodes" / "chunk-000" / "file-000.parquet"
      p.parent.mkdir(parents=True, exist_ok=True)
      pq.write_table(pa.table(cols), str(p))
      ds.files.append("meta/episodes/chunk-000/file-000.parquet")
    else:
      _write_jsonl(root / "meta" / "episodes" / "chunk-000" / "file-000.jsonl", ep_rows)
      ds.files.append("meta/episodes/chunk-000/file-000.jsonl")
  else:
    _write_jsonl(root / "meta" / "episodes.jsonl", [{"episode_index": r["episode_index"], "tasks": r["tasks"], "length": r["length"]} for r in ep_rows])
    ds.files.append("meta/episodes.jsonl")

  # ---- frame tables (+ images) ----
  def frame_columns(eps: Sequence[MiniEpisode], global_start: int) -> Dict[str, Any]:
    cols: Dict[str, Any] = {}
    g = global_start
    if image_mode == "embedded":
      for cam, key in cam_keys.items():
        if data_format == "parquet":
          cols[key] = [{"bytes": _png_bytes(e.images[cam][i]), "path": f"frame_{i:06d}.png"} for e in eps for i in range(n_steps)]
        else:
          cols[key] = np.concatenate([e.images[cam] for e in eps], axis=0)
    cols[state_key] = np.concatenate([e.state for e in eps], axis=0)
    cols[action_key] = np.concatenate([e.action for e in eps], axis=0)
    cols["timestamp"] = np.concatenate([e.timestamps for e in eps]).astype(np.float32)
    cols["frame_index"] = np.concatenate([np.arange(n_steps) for _ in eps]).astype(np.int64)
    cols["episode_index"] = np.concatenate([np.full(n_steps, e.episode_index) for e in eps]).astype(np.int64)
    cols["index"] = np.arange(g, g + n_steps * len(eps)).astype(np.int64)
    cols["task_index"] = np.concatenate([np.full(n_steps, e.task_index) for e in eps]).astype(np.int64)
    return cols

  image_cols = list(cam_keys.values()) if image_mode == "embedded" else []
  if is_v3:
    cols = frame_columns(ds.episodes, 0)
    if data_format == "parquet":
      _write_frame_table_parquet(root / "data" / "chunk-000" / "file-000.parquet", cols, image_cols, fixed_size=False)
      ds.files.append("data/chunk-000/file-000.parquet")
    else:
      _write_frame_table_npz(root / "data" / "chunk-000" / "file-000.npz", cols)
      ds.files.append("data/chunk-000/file-000.npz")
  else:
    start = 0
    for e in ds.episodes:
      cols = frame_columns([e], start)
      start += n_steps
      rel = f"data/chunk-000/episode_{e.episode_index:06d}"
      if data_format == "parquet":
        _write_frame_table_parquet(root / (rel + ".parquet"), cols, image_cols, fixed_size=True)
        ds.files.append(rel + ".parquet")
      else:
        _write_frame_table_npz(root / (rel + ".npz"), cols)
        ds.files.append(rel + ".npz")

  if image_mode == "png_dir":
    from PIL import Image

    for e in ds.episodes:
      for cam, key in cam_keys.items():
        d = root / "images" / key / f"episode_{e.episode_index:06d}"
        d.mkdir(parents=True, exist_ok=True)
        for i in range(n_steps):
          Image.fromarray(e.images[cam][i]).save(d / f"frame_{i:06d}.png")
        ds.files.append(f"images/{key}/episode_{e.episode_index:06d}/ ({n_steps} PNGs)")
  elif image_mode == "video":
    for cam, key in cam_keys.items():
      if is_v3:
        frames = np.concatenate([e.images[cam] for e in ds.episodes], axis=0)
        rel = info["video_path"].format(video_key=key, chunk_index=0, file_index=0)
        _write_video(root / rel, frames, fps, video_codec)
        ds.files.append(rel)
      else:
        for e in ds.episodes:
          rel = info["video_path"].format(video_key=key, episode_chunk=0, episode_index=e.episode_index)
          _write_video(root / rel, e.images[cam], fps, video_codec)
          ds.files.append(rel)

  _write_json(root / "SYNTHETIC_FIXTURE.json", {"note": SYNTHETIC_LABEL, "layout": layout, "data_format": data_format, "image_mode": image_mode, "files": ds.files})
  return ds


def main(argv: Optional[Sequence[str]] = None) -> int:
  ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
  ap.add_argument("--out", required=True)
  ap.add_argument("--episodes", type=int, default=2)
  ap.add_argument("--steps", type=int, default=10)
  ap.add_argument("--layout", default="v3", choices=("v3", "v2"))
  ap.add_argument("--image-mode", default="embedded", choices=("embedded", "png_dir", "video"))
  ap.add_argument("--data-format", default="auto", choices=("auto", "parquet", "fallback"))
  ap.add_argument("--video-codec", default="ffv1")
  ap.add_argument("--seed", type=int, default=0)
  args = ap.parse_args(argv)
  ds = make_mini_lerobot(args.out, n_episodes=args.episodes, n_steps=args.steps, layout=args.layout, image_mode=args.image_mode, data_format=args.data_format, video_codec=args.video_codec, seed=args.seed)
  print(f"{SYNTHETIC_LABEL}\nwrote {ds.layout} layout ({ds.data_format}, {ds.image_mode}) to {ds.root}")
  for f in ds.files:
    print("  ", f)
  return 0


if __name__ == "__main__":
  sys.exit(main())
